query:
What does the following GDScript function do?:

func Sorted_Attribute_Transfer(From_Vertices, To_Vertices):
	var SortListA = From_Vertices.keys()
	SortListA.sort_custom(func(X, Y) -> bool:
		return To_Vertices[X] < To_Vertices[Y])
	var SortListB = SortListA.duplicate(true)
	SortListB.sort_custom(func(X, Y) -> bool:
		return From_Vertices[X] < From_Vertices[Y])
	var NVertices = To_Vertices.duplicate(true)
	for I in range(0,len(From_Vertices)):
		NVertices[SortListA[I]] = From_Vertices[SortListB[I]]
	return NVertices

